import { writeFile } from "node:fs/promises";

const origin = "https://code.aicodeme.xyz";
const path = process.env.ARTIFACT_PATH;
if (!/^\/v1\/tasks\/[^/]+\/artifacts\/[^/]+\/content$/.test(path ?? "")) {
  throw new Error("填写本站返回的任务制品 content 路径");
}
const response = await fetch(new URL(path, origin), {
  headers: { Authorization: "Bearer " + process.env.AICODEME_API_KEY },
  redirect: "error",
});
if (!response.ok) throw new Error("下载失败 " + response.status);
await writeFile("result.png", Buffer.from(await response.arrayBuffer()));

