import base64
from pathlib import Path

for candidate in result.get("candidates", []):
    for index, part in enumerate(candidate.get("content", {}).get("parts", [])):
        image = part.get("inline_data") or part.get("inlineData")
        if image:
            mime = image.get("mime_type") or image.get("mimeType")
            suffix = {"image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp"}[mime]
            Path(f"gemini-{index}{suffix}").write_bytes(base64.b64decode(image["data"]))

import os
from google import genai
from google.genai import types

client = genai.Client(
    api_key=os.environ["AICODEME_API_KEY"],
    http_options=types.HttpOptions(
        base_url="https://code.aicodeme.xyz", api_version="v1beta"
    ),
)
response = client.models.generate_content(
    model=os.environ["GEMINI_IMAGE_MODEL"],
    contents="一张海边灯塔的插画",
    config=types.GenerateContentConfig(response_modalities=["TEXT", "IMAGE"]),
)
for candidate in response.candidates or []:
    for part in (candidate.content.parts if candidate.content else []):
        if part.text:
            print(part.text)
        if part.inline_data and part.inline_data.data:
            print(part.inline_data.mime_type, len(part.inline_data.data))

const model = encodeURIComponent(process.env.GEMINI_IMAGE_MODEL);
const response = await fetch(
  "https://code.aicodeme.xyz/v1beta/models/" + model + ":generateContent",
  {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-goog-api-key": process.env.AICODEME_API_KEY,
    },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ text: "一张海边灯塔的插画" }] }],
      generationConfig: { responseModalities: ["TEXT", "IMAGE"] },
    }),
  },
);
if (!response.ok) throw new Error(await response.text());
const result = await response.json();
if (response.status === 202) {
  console.log("任务 ID:", result.id);
} else {
  for (const candidate of result.candidates ?? []) {
    for (const part of candidate.content?.parts ?? []) {
      if (part.text) console.log(part.text);
      if (part.inlineData) console.log("图片类型:", part.inlineData.mimeType);
    }
  }
}
